"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import {
    Upload,
    X,
    Crosshair,
    Sparkles,
    Clock,
    Tag,
    CreditCard,
    MapPin,
    Loader2,
    Eye,
    AlertCircle
} from "lucide-react";
import { Button } from "@/app/components/ui/button";
import { Input } from "@/app/components/ui/input";
import { Label } from "@/app/components/ui/label";
import { Card } from "@/app/components/ui/card";
import { Switch } from "@/app/components/ui/switch";
import { Badge } from "@/app/components/ui/badge";
import { Textarea } from "@/app/components/ui/textarea";
import Header from "@/app/components/Header";
import Footer from "@/app/components/Footer";
import { addItem } from "@/app/lib/api";
import { toast } from "sonner";
import Image from "next/image";
import { useAuth } from "../context/AuthContext";
import ProductCard from "@/app/components/ProductCard";

export default function UploadPage() {
    const router = useRouter();
    const { isBuyerMode, user } = useAuth();
    const [loading, setLoading] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const [imagePreviews, setImagePreviews] = useState<string[]>([]);
    const [formData, setFormData] = useState({
        title: "",
        category: "",
        condition: "",
        price: "",
        content: "",
        location: "",
        images: [] as File[],
        allowBidding: false,
        minBid: "",
        expiry: "",
        offerPrice: "",
        paymentMethods: [] as string[],
    });

    // Load data from localStorage on mount
    useEffect(() => {
        const savedData = localStorage.getItem("uploadFormData");
        if (savedData) {
            try {
                const parsed = JSON.parse(savedData);
                setFormData(prev => ({
                    ...prev,
                    ...parsed,
                    images: [] // Images cannot be stored in localStorage easily
                }));
            } catch (e) {
                console.error("Failed to parse saved form data", e);
            }
        }
    }, []);

    // Save data to localStorage when formData changes
    useEffect(() => {
        const dataToSave = { ...formData };
        const { images, ...serializableData } = dataToSave;
        localStorage.setItem("uploadFormData", JSON.stringify(serializableData));
    }, [formData]);

    const clearForm = () => {
        setFormData({
            title: "",
            category: "",
            condition: "",
            price: "",
            content: "",
            location: "",
            images: [],
            allowBidding: false,
            minBid: "",
            expiry: "",
            offerPrice: "",
            paymentMethods: [],
        });
        setImagePreviews([]);
        localStorage.removeItem("uploadFormData");
        toast.success("Form cleared");
    };

    const isFormEmpty = () => {
        return !formData.title && !formData.category && !formData.condition && !formData.price && !formData.content && !formData.location && formData.images.length === 0;
    };

    const categories = [
        "Electronics", "Fashion", "Home & Garden", "Sports", "Collectibles", "Vehicles", "Other"
    ];

    const conditions = ["New", "Like New", "Excellent", "Good", "Fair", "Poor"];

    const handleLocationFetch = () => {
        if (!navigator.geolocation) {
            toast.error("Geolocation is not supported by your browser");
            return;
        }

        toast.loading("Fetching your location...", { id: "location" });

        navigator.geolocation.getCurrentPosition(
            async (position) => {
                const { latitude, longitude } = position.coords;
                try {
                    const response = await fetch(
                        `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&addressdetails=1`
                    );
                    const data = await response.json();
                    
                    if (data.address) {
                        const addr = data.address;
                        const parts = [];

                        // Landmarks/Amenities
                        if (addr.amenity && addr.amenity !== addr.hospital) parts.push(addr.amenity);
                        if (addr.building) parts.push(addr.building);
                        if (addr.landmark) parts.push(addr.landmark);

                        // Street/Road
                        if (addr.road) parts.push(addr.road);

                        // Locality/Suburb
                        if (addr.suburb) parts.push(addr.suburb);
                        else if (addr.neighbourhood) parts.push(addr.neighbourhood);
                        else if (addr.hamlet) parts.push(addr.hamlet);
                        else if (addr.village) parts.push(addr.village);

                        // City/District
                        if (addr.city) parts.push(addr.city);
                        else if (addr.town) parts.push(addr.town);

                        if (addr.district) parts.push(addr.district);
                        else if (addr.county) parts.push(addr.county);

                        // State
                        if (addr.state) parts.push(addr.state);

                        const formattedAddress = parts.filter(Boolean).join(", ");
                        setFormData(prev => ({ ...prev, location: formattedAddress }));
                        toast.success("Location updated!", { id: "location" });
                    }
                } catch (error) {
                    toast.error("Failed to fetch address", { id: "location" });
                }
            },
            (error) => {
                toast.error("Geolocation access denied", { id: "location" });
            }
        );
    };

    const handleGenerateDescription = async () => {
        if (!formData.title) return;

        setLoading(true);
        toast.loading("Generating professional description...", { id: "gen" });

        // Simulate AI thinking time
        await new Promise(resolve => setTimeout(resolve, 1500));

        const title = formData.title.toLowerCase();
        const condition = formData.condition || "Excellent";
        const category = formData.category || "Item";

        let specs = "";
        if (title.includes("iphone") || title.includes("samsung") || title.includes("pixel") || title.includes("phone")) {
            const isLatest = title.includes("15") || title.includes("16") || title.includes("s24") || title.includes("s23");
            specs = `\n\n✨ TECHNICAL SPECIFICATIONS:\n` +
                `- Display: ${isLatest ? 'Super Retina XDR / Dynamic AMOLED 2X' : 'High Resolution OLED/LCD'}\n` +
                `- RAM: ${isLatest ? '8GB / 12GB' : '6GB / 8GB'} for smooth multitasking\n` +
                `- Storage (ROM): 128GB / 256GB / 512GB\n` +
                `- Camera: Advanced Multi-lens System with Night Mode & Pro Video\n` +
                `- Battery: Long-lasting ${isLatest ? '5000mAh' : '4500mAh'} equivalent with Fast Charging`;
        } else if (title.includes("laptop") || title.includes("macbook") || title.includes("dell") || title.includes("hp")) {
            specs = `\n\n💻 TECHNICAL SPECIFICATIONS:\n` +
                `- Processor: High-Performance Multi-core Chip\n` +
                `- RAM: 16GB / 32GB High Speed Memory\n` +
                `- Storage: 512GB / 1TB NVMe SSD\n` +
                `- Display: Crystal Clear Anti-glare Screen\n` +
                `- Graphics: Integrated/Dedicated GPU for seamless visuals`;
        }

        const templates = [
            `🚀 **FOR SALE: ${formData.title}** 🚀\n\nAre you looking for a premium ${category} that delivers top-tier performance? Look no further! This ${formData.title} is in ${condition} condition and has been meticulously cared for. Whether you're a professional or a casual user, this device will exceed your expectations.\n\n🌟 KEY HIGHLIGHTS:\n- Exceptional Performance & Speed\n- Sleek and Modern Design\n- 100% Fully Functional & Tested\n- Great Value for Price${specs}\n\n✅ CONDITION DETAILS:\n- Overall Condition: ${condition}\n- No hidden defects or issues\n- Screen/Body: Well preserved\n\nDon't miss out on this fantastic opportunity! This ${formData.title} is priced to sell quickly. Direct message me now to grab it before someone else does!`,
            
            `🔥 **GREAT DEAL: ${formData.title}** 🔥\n\nLooking to upgrade? I'm selling my ${formData.title} which is in ${condition} condition. This ${category} offers a perfect blend of style and utility, making it an essential addition to your daily tech lineup. Carefully used and ready for its new owner!${specs}\n\n💎 WHY BUY THIS?\n- Verified Quality & Reliability\n- Premium Build Materials\n- Excellent Battery Efficiency\n- Optimized Software Experience\n\n📦 WHAT'S INCLUDED:\n- ${formData.title}\n- Original/Standard Essentials\n\nPrice is negotiable for serious buyers. First come, first served!`,

            `✨ **PREMIUM ${formData.title.toUpperCase()} FOR SALE** ✨\n\nOwn this incredible ${formData.title} today! Known for its reliability and industry-leading features, this ${category} is currently in ${condition} state and performs like a charm. Perfect for anyone who wants a high-quality device without paying full retail price.${specs}\n\n🏆 SPECIAL FEATURES:\n- Immersive Display & Audio\n- Powerful Processing Capabilities\n- Clean and Maintained Aesthetics\n- Future-proof Technology\n\nEverything works perfectly as expected. I am selling this because I've recently upgraded. Feel free to ask any questions!`
        ];

        const description = templates[Math.floor(Math.random() * templates.length)];
        
        setFormData(prev => ({ ...prev, content: description }));
        toast.success("Professional description created!", { id: "gen" });
        setLoading(false);

        setTimeout(() => {
            const textarea = document.getElementById("content") as HTMLTextAreaElement;
            if (textarea) {
                textarea.style.height = "auto";
                textarea.style.height = `${textarea.scrollHeight}px`;
            }
        }, 100);
    };

    const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value.replace(/[^0-9]/g, "");
        setFormData({ ...formData, price: value });
    };

    const handleMinBidChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value.replace(/[^0-9]/g, "");
        const listedPrice = parseFloat(formData.price) || 0;
        const maxAllowedBid = listedPrice * 0.05;

        if (parseFloat(value) > maxAllowedBid && value !== "") {
            toast.error("Invalid Initial Bid", { 
                description: `Initial bid must be 5% or less of listed price (Max: रु ${maxAllowedBid.toFixed(0)})` 
            });
            return;
        }
        setFormData({ ...formData, minBid: value });
    };

    const togglePaymentMethod = (method: string) => {
        setFormData(prev => ({
            ...prev,
            paymentMethods: prev.paymentMethods.includes(method)
                ? prev.paymentMethods.filter(m => m !== method)
                : [...prev.paymentMethods, method]
        }));
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement> | FileList) => {
        const files = 'target' in e ? e.target.files : e;
        if (files) {
            const newFiles = Array.from(files);
            setFormData(prev => ({ ...prev, images: [...prev.images, ...newFiles] }));

            newFiles.forEach(file => {
                const reader = new FileReader();
                reader.onloadend = () => {
                    setImagePreviews(prev => [...prev, reader.result as string]);
                };
                reader.readAsDataURL(file);
            });
        }
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const files = e.dataTransfer.files;
        if (files && files.length > 0) {
            handleImageChange(files);
        }
    };

    const removeImage = (index: number) => {
        const newImages = [...formData.images];
        newImages.splice(index, 1);
        const newPreviews = [...imagePreviews];
        newPreviews.splice(index, 1);
        setFormData({ ...formData, images: newImages });
        setImagePreviews(newPreviews);
    };

    const getWordCount = (text: string) => {
        return text.trim().split(/\s+/).filter(Boolean).length;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (getWordCount(formData.content) > 999) {
            toast.error("Description too long", { description: "Maximum 999 words allowed" });
            return;
        }

        if (formData.images.length === 0) {
            toast.error("Image Required", { description: "Please upload at least one image of your item" });
            return;
        }

        setLoading(true);
        toast.loading("Listing your item...", { id: "upload" });

        try {
            const data = new FormData();
            data.append("title", formData.title);
            data.append("content", formData.content);
            data.append("price", formData.price);
            data.append("location", formData.location);
            if (formData.category) data.append("category", formData.category);
            if (formData.condition) data.append("condition", formData.condition);
            data.append("allowBidding", String(formData.allowBidding));
            if (formData.allowBidding && formData.minBid) {
                data.append("minBid", formData.minBid);
            }
            if (formData.expiry) data.append("expiry", formData.expiry);
            if (formData.offerPrice) data.append("offerPrice", formData.offerPrice);
            if (formData.paymentMethods.length > 0) {
                data.append("paymentMethods", JSON.stringify(formData.paymentMethods));
            }

            formData.images.forEach(image => {
                data.append("images", image);
            });

            await addItem(data);
            toast.success("Success!", { id: "upload", description: "Your item has been uploaded successfully" });

            setFormData({
                title: "", category: "", condition: "", price: "", content: "", location: "", allowBidding: false, minBid: "", expiry: "", offerPrice: "", paymentMethods: [], images: []
            });
            setImagePreviews([]);
            localStorage.removeItem("uploadFormData");
            setTimeout(() => router.push("/"), 1500);
        } catch (error: any) {
            toast.error("Upload Failed", { id: "upload", description: error.message || "Failed to upload item." });
        } finally {
            setLoading(false);
        }
    };

    if (isBuyerMode) {
        return (
            <div className="min-h-screen bg-background flex flex-col">
                <Header />
                <main className="flex-1 container mx-auto px-4 py-16 text-center">
                    <Card className="max-w-md mx-auto p-8 space-y-4">
                        <AlertCircle className="h-12 w-12 text-yellow-500 mx-auto" />
                        <h1 className="text-2xl font-bold">Seller Mode Required</h1>
                        <p className="text-muted-foreground italic">
                            You are currently in Buyer Mode. Please toggle to Seller Mode in the header to upload items.
                        </p>
                        <Button onClick={() => router.push("/")} variant="outline" className="w-full">
                            Return to Homepage
                        </Button>
                    </Card>
                </main>
                <Footer />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-background flex flex-col">
            <Header />

            <main className="flex-1 container mx-auto px-4 py-8">
                <div className="flex flex-col md:flex-row gap-6">
                    {/* Left Column - Image Gallery & Details (50%) */}
                    <div className="w-full md:w-1/2 space-y-4">
                        <div className="flex justify-between items-center bg-card p-3 rounded-lg border shadow-sm">
                            <h2 className="text-xl font-bold flex items-center gap-2">
                                <Upload className="h-5 w-5 text-primary" /> Listing Details
                            </h2>
                            {!isFormEmpty() && (
                                <Button 
                                    type="button" 
                                    variant="ghost" 
                                    size="sm" 
                                    onClick={clearForm}
                                    className="text-xs h-8 flex items-center gap-1 hover:bg-destructive/10 hover:text-destructive transition-all font-semibold"
                                >
                                    <X className="h-3 w-3" /> CLEAR ALL
                                </Button>
                            )}
                        </div>

                        <Card className="p-6 md:p-8 shadow-sm border overflow-hidden">
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div className="flex items-center justify-between gap-4">
                                    <div className="flex-1">
                                        <Input
                                            placeholder="Item Title (e.g. iPhone 15 Pro)"
                                            value={formData.title}
                                            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                                            className="text-lg font-bold h-12 bg-muted/30 focus:bg-background transition-all"
                                            required
                                        />
                                    </div>
                                    <Button disabled={loading} className="px-8 h-12 shadow-lg hover:translate-y-[-1px] transition-all active:scale-95">
                                        {loading ? <Loader2 className="animate-spin h-5 w-5" /> : "LIST ITEM"}
                                    </Button>
                                </div>

                                <div className="space-y-4">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label htmlFor="price" className="text-sm font-semibold">Listed Price (रु) <span className="text-red-500">*</span></Label>
                                            <Input
                                                id="price"
                                                placeholder="Enter price"
                                                value={formData.price}
                                                onChange={handlePriceChange}
                                                required
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <div className="flex justify-between items-center">
                                                <Label className="text-sm font-semibold">Allow Bidding</Label>
                                                <Switch
                                                    checked={formData.allowBidding}
                                                    onCheckedChange={(checked) => setFormData({ ...formData, allowBidding: checked })}
                                                />
                                            </div>
                                            <Input
                                                placeholder="Min Bid (Max 5% of Price)"
                                                value={formData.minBid}
                                                onChange={handleMinBidChange}
                                                disabled={!formData.allowBidding || !formData.price}
                                                className={`h-9 transition-all ${!formData.allowBidding ? 'opacity-30' : 'opacity-100'}`}
                                            />
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold flex items-center gap-1 opacity-70">
                                                <Clock className="h-3 w-3" /> Expiry
                                            </Label>
                                            <select 
                                                className="w-full h-9 px-3 text-sm rounded-md border border-input bg-background"
                                                value={formData.expiry}
                                                onChange={(e) => setFormData({...formData, expiry: e.target.value})}
                                            >
                                                <option value="">No Expiry</option>
                                                <option value="3days">3 Days</option>
                                                <option value="7days">7 Days</option>
                                                <option value="30days">30 Days</option>
                                            </select>
                                        </div>
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold flex items-center gap-1 opacity-70">
                                                <Tag className="h-3 w-3" /> Offer Price (Optional)
                                            </Label>
                                            <Input
                                                placeholder="Special offer"
                                                value={formData.offerPrice}
                                                onChange={(e) => setFormData({...formData, offerPrice: e.target.value.replace(/[^0-9]/g, "")})}
                                                className="h-9"
                                            />
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <Label className="text-sm font-semibold flex items-center gap-1 opacity-70">
                                            <CreditCard className="h-3 w-3" /> Accepted Payments
                                        </Label>
                                        <div className="flex flex-wrap gap-2">
                                            {['eSewa', 'Khalti', 'Cash', 'Bank'].map((method) => (
                                                <button
                                                    key={method}
                                                    type="button"
                                                    onClick={() => togglePaymentMethod(method)}
                                                    className={`px-3 py-1 text-[10px] uppercase font-bold rounded-full border transition-all ${
                                                        formData.paymentMethods.includes(method)
                                                            ? 'bg-primary text-primary-foreground border-primary'
                                                            : 'bg-muted/50 text-muted-foreground border-transparent hover:bg-muted'
                                                    }`}
                                                >
                                                    {method}
                                                </button>
                                            ))}
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <Label htmlFor="location" className="text-sm font-semibold">Location <span className="text-red-500">*</span></Label>
                                        <div className="relative group">
                                            <MapPin className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground group-focus-within:text-primary transition-colors" />
                                            <Input
                                                id="location"
                                                placeholder="Specific address (e.g. Kist Hospital, Gwarko)"
                                                value={formData.location}
                                                onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                                                className="pl-10 pr-10 bg-muted/10 transition-all focus:bg-background"
                                                required
                                            />
                                            <button
                                                type="button" onClick={handleLocationFetch}
                                                className="absolute right-3 top-2.5 text-muted-foreground hover:text-primary transition-colors"
                                                title="Get specific location"
                                            >
                                                <Crosshair className="h-4 w-4" />
                                            </button>
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center">
                                            <Label htmlFor="content" className="text-sm font-semibold">Description <span className="text-red-500">*</span></Label>
                                            <span className={`text-[10px] ${getWordCount(formData.content) > 999 ? 'text-red-500 font-bold' : 'text-muted-foreground'}`}>
                                                {getWordCount(formData.content)} / 999 WORDS
                                            </span>
                                        </div>
                                        <div className="relative group/desc">
                                            <Textarea
                                                id="content"
                                                placeholder="Describe your item's features, specs, and condition..."
                                                value={formData.content}
                                                onChange={(e) => {
                                                    const target = e.target;
                                                    setFormData({ ...formData, content: target.value });
                                                    target.style.height = "auto";
                                                    target.style.height = `${target.scrollHeight}px`;
                                                }}
                                                className="w-full min-h-[56px] px-3 py-2 text-sm rounded-md border border-input bg-background focus:outline-none focus:ring-2 focus:ring-ring transition-all overflow-hidden"
                                                required
                                            />
                                            <div className="absolute right-2 bottom-2 flex items-center gap-2">
                                                <Button
                                                    type="button"
                                                    onClick={handleGenerateDescription}
                                                    disabled={!formData.title || loading}
                                                    size="sm"
                                                    className={`h-7 px-2 text-[10px] font-bold tracking-tight shadow-lg transition-all ${!formData.title ? 'opacity-30' : 'bg-primary hover:bg-primary/90 opacity-100'}`}
                                                >
                                                    <Sparkles className="h-3 w-3 mr-1" /> GENERATE
                                                </Button>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold opacity-70 uppercase text-[10px] tracking-widest">Image Upload</Label>
                                            <div
                                                onDragOver={handleDragOver}
                                                onDragLeave={handleDragLeave}
                                                onDrop={handleDrop}
                                                className={`grid grid-cols-4 gap-2 p-2 rounded-lg border-2 transition-all duration-300 ${isDragging ? 'border-primary border-solid bg-primary/5 scale-[1.02] shadow-xl' : 'border-transparent'}`}
                                            >
                                                {imagePreviews.map((preview, index) => (
                                                    <div key={index} className="relative aspect-square rounded-md overflow-hidden border bg-muted shadow-sm hover:scale-105 transition-transform group/img">
                                                        <Image src={preview} alt="Upload" fill className="object-cover" />
                                                        <button
                                                            type="button" onClick={() => removeImage(index)}
                                                            className="absolute top-1 right-1 bg-black/70 text-white rounded-full p-1 opacity-0 group-hover/img:opacity-100 transition-opacity"
                                                        >
                                                            <X className="h-3 w-3" />
                                                        </button>
                                                    </div>
                                                ))}
                                                <label className={`flex flex-col items-center justify-center aspect-square border-2 border-dashed rounded-md cursor-pointer transition-all duration-300 ${isDragging ? 'border-primary bg-primary/10' : 'border-muted-foreground/20 hover:bg-muted/50'}`}>
                                                    <input type="file" multiple accept="image/*" onChange={handleImageChange} className="hidden" />
                                                    <Upload className={`h-5 w-5 ${isDragging ? 'text-primary' : 'text-muted-foreground/60'}`} />
                                                    <span className="text-[8px] font-black mt-1">{isDragging ? 'DROP' : 'ADD'}</span>
                                                </label>
                                            </div>
                                        </div>

                                        <div className="space-y-4">
                                            <div className="space-y-2">
                                                <Label className="text-sm font-semibold opacity-70">Category</Label>
                                                <select
                                                    value={formData.category}
                                                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                                                    className="w-full h-10 px-3 text-sm rounded-md border border-input bg-background"
                                                >
                                                    <option value="">Select category</option>
                                                    {categories.map((cat) => <option key={cat} value={cat}>{cat}</option>)}
                                                </select>
                                            </div>
                                            <div className="space-y-2">
                                                <Label className="text-sm font-semibold opacity-70">Condition</Label>
                                                <select
                                                    value={formData.condition}
                                                    onChange={(e) => setFormData({ ...formData, condition: e.target.value })}
                                                    className="w-full h-10 px-3 text-sm rounded-md border border-input bg-background"
                                                >
                                                    <option value="">Select condition</option>
                                                    {conditions.map((cond) => <option key={cond} value={cond}>{cond}</option>)}
                                                </select>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </form>
                        </Card>
                    </div>

                    {/* Right Column - Live Preview (sticky) */}
                    <div className="w-full md:w-1/2 lg:w-[400px]">
                        <div className="sticky top-24 space-y-4">
                            <div className="flex items-center justify-between px-2">
                                <h2 className="text-xl font-bold flex items-center gap-2">
                                    <Eye className="h-5 w-5 text-primary" /> Preview
                                </h2>
                                <Badge variant="outline" className="text-[10px] font-bold transition-all">
                                    BUYER VIEW
                                </Badge>
                            </div>

                            <div className="max-w-sm mx-auto w-full group transition-all duration-500 hover:scale-[1.02]">
                                <ProductCard
                                    title={formData.title || "Item Title"}
                                    price={Number(formData.price) || 0}
                                    image={imagePreviews[0] || ""}
                                    location={formData.location || "Location"}
                                    timePosted="Just now"
                                    isBiddable={formData.allowBidding}
                                    showEdit={false}
                                />
                            </div>

                            <Card className="p-4 bg-primary/5 border-dashed border-primary/20">
                                <div className="flex gap-3">
                                    <AlertCircle className="h-5 w-5 text-primary shrink-0" />
                                    <p className="text-[11px] text-muted-foreground leading-relaxed">
                                        Detailed descriptions and accurate locations increase your chances of a quick sale by up to <strong>40%</strong>. Make sure your photos are clear!
                                    </p>
                                </div>
                            </Card>
                        </div>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
}
